files.content:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  min-height: 100vh;
  margin: 0;
  padding: 40px;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-color: #fff;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
}

a {
  display: block;
  color: currentColor;
  text-decoration: none;
}

ul {
  border: 1px solid #000;
  padding: 0;
  list-style: none;
}

ul li:hover {
  background-color: #80d994;
}

.menu__list {
  display: flex;
  flex-direction: column;
  width: fit-content;
}

.menu__list li:not(:last-child) {
  border-bottom: 1px solid currentColor;
}

.menu__list a {
  padding: 20px 40px;
  font-weight: bold;
  text-align: center;
  text-transform: uppercase;
}
.menu__list > li {
  background-color: #6dc1fd;
  position: relative;
}
